// Signs the request for overdue loans with N8N_TO_CONVEX_SECRET. A GET has no
// body, so the signature covers `${timestamp}.` (an empty body).
const crypto = require('crypto');

const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set on the n8n server');

const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { timestamp, signature } }];

// Convex answers { date, loans: [...] } and leaves out loans already reminded
// today, so re-running this workflow never reminds anyone twice in one day.
// With no overdue loans there are no items, and the run ends here.
const { loans = [] } = $input.first().json;
return loans.map((loan) => ({ json: loan }));

// Only the borrower's first name and email, the tool name and the due date reach n8n.
const { requestId, idempotencyKey, borrower, toolName, dueDate, daysOverdue } = $json;
const late = daysOverdue === 1 ? '1 day' : `${daysOverdue} days`;

return {
  json: {
    requestId,
    idempotencyKey,
    to: borrower.email,
    subject: `Reminder: the ${toolName} was due back on ${dueDate}`,
    text: `Hi ${borrower.name}, the ${toolName} you borrowed was due back on ${dueDate} (${late} ago). Please return it, or message the lender on LendLoop.`,
    activity: `Overdue reminder sent to the borrower (${late} late)`,
  },
};

// Reports each reminder's outcome to LendLoop. When Resend refuses an email after
// the retries, the send node passes on an item with `error` set, and the status
// becomes "failed". Convex skips only "sent" reminders, so re-running today
// retries the failed ones. Reads the reminder from "Compose reminder", because
// $json here is Resend's response.
// The key (overdue:<loan>:<date>) comes from Convex, so retries update one entry.
const crypto = require('crypto');

const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set on the n8n server');

const reminder = $('Compose reminder').item.json;
const failed = Boolean($json.error);
const body = JSON.stringify({
  idempotencyKey: reminder.idempotencyKey,
  borrowRequestId: reminder.requestId,
  type: 'overdue_reminder',
  status: failed ? 'failed' : 'sent',
  message: failed ? 'Overdue reminder could not be sent' : reminder.activity,
});
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };
